import { describe, expect, it } from 'vitest';
import { receiverView } from './Solution';

/**
 * 断言由 gen.py 里同一个 receiver_view() 模型生成，不手抄 ——
 * react-vitest 题的判分事实来源就是这份测试文件，抄错一次就永久错一次。
 * 契约型用例断言到**消息**：只写 .toThrow() 会让几条"都该抛错"的用例收敛成同一条。
 */
describe('receiverView：收件人字段三态语义的视图模型', () => {
  it("基线：待发货 + 未打标 + 密文 ⇒ 唯一可解密的形态", () => {
    expect(receiverView({"status": 1, "risk": 0, "stored": "cipher"})).toEqual({"reason": "ok", "text": "可查看", "tone": "ok", "canDecrypt": true, "metricBucket": "visible", "ariaLabel": "收件人信息：可查看", "countsAsMissingForQuality": false});
  });
  it("风控审核中必须渲染成\"暂不可查看\"，不能渲染成\"数据缺失\"", () => {
    expect(receiverView({"status": 1, "risk": 1, "stored": "cipher"})).toEqual({"reason": "risk-hold", "text": "审核中 · 暂不可查看", "tone": "warn", "canDecrypt": false, "metricBucket": "policy-hidden", "ariaLabel": "收件人信息：审核中 · 暂不可查看", "countsAsMissingForQuality": false});
  });
  it("已发货：状态本身就不该再展示收件人信息", () => {
    expect(receiverView({"status": 2, "risk": 0, "stored": "cipher"})).toEqual({"reason": "not-awaiting-shipment", "text": "已发货 · 不再提供", "tone": "muted", "canDecrypt": false, "metricBucket": "policy-hidden", "ariaLabel": "收件人信息：已发货 · 不再提供", "countsAsMissingForQuality": false});
  });
  it("整列没返回：这一种才允许进\"数据缺失\"的分子", () => {
    expect(receiverView({"status": 1, "risk": 0, "stored": "absent"})).toEqual({"reason": "no-column", "text": "数据缺失", "tone": "warn", "canDecrypt": false, "metricBucket": "pipeline-missing", "ariaLabel": "收件人信息：数据缺失", "countsAsMissingForQuality": true});
  });
  it("库里是明文：禁止展示，且归到完整性问题而不是缺失", () => {
    expect(receiverView({"status": 1, "risk": 0, "stored": "plain"})).toEqual({"reason": "not-ciphered", "text": "未加密 · 禁止展示", "tone": "warn", "canDecrypt": false, "metricBucket": "integrity-broken", "ariaLabel": "收件人信息：未加密 · 禁止展示", "countsAsMissingForQuality": false});
  });
  it("退化：已签收 + 审核中 + 缺列三件事同时成立时，缺列优先（管道故障最该被看见）", () => {
    expect(receiverView({"status": 3, "risk": 1, "stored": "absent"})).toEqual({"reason": "no-column", "text": "数据缺失", "tone": "warn", "canDecrypt": false, "metricBucket": "pipeline-missing", "ariaLabel": "收件人信息：数据缺失", "countsAsMissingForQuality": true});
  });
  it("边界：已发货优先于审核中（状态是更强的拒绝理由）", () => {
    expect(receiverView({"status": 3, "risk": 1, "stored": "cipher"})).toEqual({"reason": "not-awaiting-shipment", "text": "已发货 · 不再提供", "tone": "muted", "canDecrypt": false, "metricBucket": "policy-hidden", "ariaLabel": "收件人信息：已发货 · 不再提供", "countsAsMissingForQuality": false});
  });
  it("非法：整行是 null", () => {
    expect(() => receiverView(null as never)).toThrow("row must be an object");
  });
  it("非法：未知订单状态", () => {
    expect(() => receiverView({"status": 9, "risk": 0, "stored": "cipher"} as never)).toThrow("unknown order status");
  });
  it("非法：筛选值 5 落进了数据", () => {
    expect(() => receiverView({"status": 5, "risk": 0, "stored": "cipher"} as never)).toThrow("filter value 5 is not a real status");
  });
  it("非法：未知风控标记", () => {
    expect(() => receiverView({"status": 1, "risk": 2, "stored": "cipher"} as never)).toThrow("unknown risk control status");
  });
  it("非法：未知存储形态", () => {
    expect(() => receiverView({"status": 1, "risk": 0, "stored": "hashed"} as never)).toThrow("unknown stored form");
  });
});

